CREATE OR REPLACE FUNCTION public.learn_performance_correct(p_tenant uuid, p_measurement uuid, p_request uuid, p_expected_review_revision integer, p_value numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
 actor_tenant uuid;actor_role text;
 parent public.measurements%rowtype;
 prior public.learn_performance_corrections%rowtype;
 previous_correction public.learn_performance_corrections%rowtype;
 current_revision integer;observed timestamptz;source_observed timestamptz;payload jsonb;receipt jsonb;
begin
 select p.tenant_id,p.role into actor_tenant,actor_role from public.profiles p where p.id=auth.uid() for share;
 if auth.uid() is null or actor_tenant is distinct from p_tenant or coalesce(actor_role,'') not in ('owner','admin')
 or exists(select 1 from public.view_as_context where actor_user_id=auth.uid() and ended_at is null and (expires_at is null or expires_at>clock_timestamp())) then
  raise exception 'Company owner/admin access required outside preview' using errcode='42501';end if;
 if p_tenant is null or p_measurement is null or p_request is null or p_expected_review_revision is null
 or p_expected_review_revision<0 or p_expected_review_revision>=2147483647
 or length(btrim(coalesce(p_reason,''))) not between 1 and 1000
 or (p_value is not null and (p_value::text in ('NaN','Infinity','-Infinity') or abs(p_value)>1.7976931348623157e308)) then
  raise exception 'A measurement, finite value or withheld value, current review revision and reason are required' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-performance-correction:'||p_request::text,0));
 select * into prior from public.learn_performance_corrections where id=p_request;
 if found then
  if prior.tenant_id<>p_tenant or prior.predecessor_id<>p_measurement or prior.corrected_by<>auth.uid()
   or prior.expected_review_revision<>p_expected_review_revision or prior.corrected_value is distinct from p_value or prior.reason<>btrim(p_reason) then
   raise exception 'Correction request identity changed' using errcode='PT409';end if;
  return jsonb_build_object('measurementId',prior.id,'predecessorId',prior.predecessor_id,'reused',true);
 end if;
 select * into parent from public.measurements where id=p_measurement and tenant_id=p_tenant for update;
 if not found or parent.subject_kind='tenant' or parent.request_payload is null then
  raise exception 'Performance observation unavailable' using errcode='22023';end if;
 if exists(select 1 from public.measurements where supersedes=parent.id) then
  raise exception 'Observation already corrected; reload the card' using errcode='PT409';end if;
 select coalesce(max(revision),0) into current_revision from public.learn_performance_reviews where measurement_id=parent.id;
 if current_revision<>p_expected_review_revision then raise exception 'Review changed; reload the card' using errcode='PT409';end if;
 if parent.value is not distinct from p_value then raise exception 'Correction must change or withhold the value' using errcode='22023';end if;
 source_observed:=parent.measured_at;
 if parent.request_payload ? 'manualCorrectionId' then
  select * into previous_correction from public.learn_performance_corrections where id=parent.id and tenant_id=p_tenant;
  if not found or parent.request_payload->>'manualCorrectionId' is distinct from parent.id::text
   or previous_correction.predecessor_id is distinct from parent.supersedes or previous_correction.corrected_value is distinct from parent.value then
   raise exception 'Correction provenance is incomplete' using errcode='PT409';end if;
  source_observed:=previous_correction.source_observed_at;
 end if;
 observed:=clock_timestamp();
 if date_trunc('milliseconds',observed)<=date_trunc('milliseconds',parent.measured_at) then
  raise exception 'Observation is too recent; retry after reloading' using errcode='PT409';end if;
 -- Only the value and correction identity change. Counts, source watermark,
 -- unit, scope, evidence and exclusions remain those of the retained parent.
 payload:=parent.request_payload||jsonb_build_object('id',p_request,'supersedes',parent.id,'value',p_value,'observedAt',observed,'review','inferred','manualCorrectionId',p_request);
 receipt:=public.learn_performance_append(p_tenant,payload,btrim(p_reason));
 if receipt->>'measurementId' is distinct from p_request::text or receipt->>'reused' is distinct from 'false' then
  raise exception 'Correction append receipt differs' using errcode='PT409';end if;
 insert into public.learn_performance_corrections(id,tenant_id,predecessor_id,previous_value,corrected_value,source_observed_at,expected_review_revision,corrected_by,reason,created_at)
 values(p_request,p_tenant,parent.id,parent.value,p_value,source_observed,p_expected_review_revision,auth.uid(),btrim(p_reason),observed);
 return jsonb_build_object('measurementId',p_request,'predecessorId',parent.id,'reused',false);
end $function$

CREATE OR REPLACE FUNCTION public.learn_performance_review(p_tenant_id uuid, p_measurement_id uuid, p_request_id uuid, p_expected_revision integer, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 prior public.learn_performance_reviews%rowtype;
 observed public.measurements%rowtype;
 current_revision integer;
begin
 if auth.uid() is null or p_tenant_id is distinct from public.current_tenant_id()
  or coalesce(public.current_user_role(),'') not in ('owner','admin')
  or exists(select 1 from public.view_as_context where actor_user_id=auth.uid()
   and ended_at is null and (expires_at is null or expires_at>now())) then
  raise exception 'Company owner/admin access required outside preview' using errcode='42501';
 end if;
 if p_measurement_id is null or p_request_id is null or p_expected_revision is null
  or p_expected_revision<0 or p_expected_revision>=2147483647
  or coalesce(p_decision,'') not in ('confirmed','disputed')
  or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 then
  raise exception 'A measurement, review decision, revision and reason are required' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-performance-review:'||p_request_id::text,0));
 select * into prior from public.learn_performance_reviews where id=p_request_id;
 if found then
  if prior.tenant_id<>p_tenant_id or prior.measurement_id<>p_measurement_id or prior.reviewed_by<>auth.uid()
   or prior.revision<>p_expected_revision+1 or prior.decision<>p_decision or prior.reason<>btrim(p_reason) then
   raise exception 'Review request identity changed' using errcode='PT409';
  end if;
  return jsonb_build_object('reviewId',prior.id,'measurementId',prior.measurement_id,'revision',prior.revision,'decision',prior.decision,'reused',true);
 end if;
 -- The adapter correction path takes this same row lock. A stale card cannot
 -- approve an observation that has already been replaced by a new source fact.
 select * into observed from public.measurements where id=p_measurement_id and tenant_id=p_tenant_id for update;
 if not found or observed.subject_kind='tenant' then
  raise exception 'Performance observation unavailable' using errcode='22023';
 end if;
 if exists(select 1 from public.measurements where supersedes=observed.id) then
  raise exception 'Observation was corrected; reload before reviewing' using errcode='PT409';
 end if;
 select coalesce(max(revision),0) into current_revision from public.learn_performance_reviews where measurement_id=observed.id;
 if current_revision<>p_expected_revision then
  raise exception 'Review changed; reload before reviewing' using errcode='PT409';
 end if;
 insert into public.learn_performance_reviews(id,tenant_id,measurement_id,revision,decision,reviewed_by,reason)
  values(p_request_id,p_tenant_id,observed.id,current_revision+1,p_decision,auth.uid(),btrim(p_reason));
 return jsonb_build_object('reviewId',p_request_id,'measurementId',observed.id,'revision',current_revision+1,'decision',p_decision,'reused',false);
end $function$

CREATE OR REPLACE FUNCTION public.learn_scorecard_save_draft(p_tenant_id uuid, p_expected_version integer, p_definition jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_kind text := p_definition->>'subjectKind';
  v_group uuid;
  v_scope text;
  v_previous jsonb;
  v_previous_version uuid;
  v_revision integer;
  v_policy uuid;
  v_version uuid := gen_random_uuid();
  v_payload jsonb;
  m jsonb;
  v_keys text[] := '{}';
  v_weight numeric := 0;
begin
  if auth.uid() is null or p_tenant_id is distinct from current_tenant_id()
     or coalesce(current_user_role(),'') not in ('owner','admin')
     or exists(select 1 from public.view_as_context where actor_user_id=auth.uid()
       and ended_at is null and (expires_at is null or expires_at>now())) then
    raise exception 'Only this company owner or admin may save scoring rules' using errcode='42501';
  end if;
  if p_expected_version is null or p_expected_version < 0 or nullif(trim(p_reason),'') is null
     or length(p_reason) > 1000 or jsonb_typeof(p_definition) is distinct from 'object' then
    raise exception 'Invalid draft request' using errcode='22023';
  end if;
  if v_kind is null or v_kind not in ('member','team','job','customer')
     or jsonb_typeof(p_definition->'name') is distinct from 'string'
     or length(trim(p_definition->>'name')) not between 1 and 200
     or jsonb_typeof(p_definition->'scaleMax') is distinct from 'number'
     or (p_definition->>'scaleMax')::numeric <= 0 or (p_definition->>'scaleMax')::numeric > 10000
     or jsonb_typeof(p_definition->'metrics') is distinct from 'array' then
    raise exception 'Invalid scorecard definition' using errcode='22023';
  end if;
  if jsonb_array_length(p_definition->'metrics') not between 1 and 50 then
    raise exception 'Choose between 1 and 50 measures' using errcode='22023';
  end if;
  v_group := nullif(p_definition->>'groupId','')::uuid;
  if v_group is not null and (v_kind not in ('member','team') or not exists
    (select 1 from org_units where tenant_id=p_tenant_id and id=v_group)) then
    raise exception 'Unknown company team group' using errcode='22023';
  end if;
  for m in select value from jsonb_array_elements(p_definition->'metrics') loop
    if jsonb_typeof(m) is distinct from 'object'
       or coalesce(m->>'key','') !~ '^[a-z][a-z0-9_.-]+$' or length(m->>'key') > 200
       or (m->>'key')=any(v_keys)
       or jsonb_typeof(m->'label') is distinct from 'string' or length(trim(m->>'label')) not between 1 and 200
       or jsonb_typeof(m->'unit') is distinct from 'string' or length(trim(m->>'unit')) not between 1 and 200
       or jsonb_typeof(m->'weight') is distinct from 'number'
       or jsonb_typeof(m->'zeroAt') is distinct from 'number'
       or jsonb_typeof(m->'fullAt') is distinct from 'number'
       or jsonb_typeof(m->'minSamples') is distinct from 'number'
       or jsonb_typeof(m->'minCoverage') is distinct from 'number'
       or jsonb_typeof(m->'maxAgeHours') is distinct from 'number'
       or jsonb_typeof(m->'sourceSystems') is distinct from 'array' then
      raise exception 'Invalid scoring measure' using errcode='22023';
    end if;
    if (m->>'weight')::numeric not between 0 and 10000
       or (m->>'zeroAt')::numeric = (m->>'fullAt')::numeric
       or (m->>'minSamples')::numeric < 1 or mod((m->>'minSamples')::numeric,1) <> 0
       or (m->>'minCoverage')::numeric <= 0 or (m->>'minCoverage')::numeric > 1
       or (m->>'maxAgeHours')::numeric <= 0
       or jsonb_array_length(m->'sourceSystems') not between 1 and 20
       or exists(select 1 from jsonb_array_elements(m->'sourceSystems') s where jsonb_typeof(s) <> 'string' or length(trim(s #>> '{}')) not between 1 and 200) then
      raise exception 'Invalid scoring targets, evidence requirements or weights' using errcode='22023';
    end if;
    perform learn_working_rule_states(m,v_kind);
    v_keys := array_append(v_keys,m->>'key');
    v_weight := v_weight + (m->>'weight')::numeric;
  end loop;
  if v_weight <= 0 then raise exception 'At least one measure needs positive weight' using errcode='22023'; end if;
  v_scope := v_kind || ':' || coalesce(v_group::text,'all');
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text || ':learn_scorecards:' || v_scope,0));
  select e.value,e.version_id into v_previous,v_previous_version
    from operating_profile_entries e join config_versions c on c.id=e.version_id and c.tenant_id=e.tenant_id
    where e.tenant_id=p_tenant_id and e.scope_kind='tenant' and e.scope_ref=v_scope
      and e.namespace='learn_scorecards' and e.key like 'definition.%'
    order by c.version desc limit 1;
  v_revision := coalesce((v_previous->>'version')::integer,0);
  if p_expected_version <> v_revision then
    raise exception 'Scoring rules changed; reload before saving' using errcode='PT409';
  end if;
  v_policy := coalesce((v_previous->>'id')::uuid,gen_random_uuid());
  v_payload := jsonb_build_object('tenantId',p_tenant_id,'id',v_policy,'version',v_revision+1,
    'name',trim(p_definition->>'name'),'status','draft','subjectKind',v_kind,'groupId',v_group,
    'scaleMax',p_definition->'scaleMax','metrics',p_definition->'metrics');
  insert into config_versions(id,tenant_id,artifact_kind,artifact_key,version,status,supersedes,author,note)
    values(v_version,p_tenant_id,'learn_scorecard',p_tenant_id::text||':'||v_scope,v_revision+1,'draft',v_previous_version,auth.uid()::text,trim(p_reason));
  insert into operating_profile_entries(tenant_id,scope_kind,scope_ref,namespace,key,value,version_id)
    values(p_tenant_id,'tenant',v_scope,'learn_scorecards','definition.'||v_version::text,v_payload,v_version);
  return v_payload;
end;
$function$

